CREATE TABLE IF NOT EXISTS competencia(id BIGINT PRIMARY KEY, nombre VARCHAR NOT NULL, descripcion VARCHAR, activo BOOLEAN NOT NULL, tipo VARCHAR NOT NULL, tecnologia VARCHAR, comportamiento VARCHAR);
CREATE TABLE IF NOT EXISTS factor(id BIGINT PRIMARY KEY, competencia BIGINT NOT NULL REFERENCES competencia, nombre VARCHAR NOT NULL, descripcion VARCHAR, orden INT, activo BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS opcion(id BIGINT PRIMARY KEY, tipo VARCHAR NOT NULL, texto VARCHAR NOT NULL, puntaje DOUBLE PRECISION NOT NULL, orden INT NOT NULL, activo BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS pregunta(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, factor BIGINT NOT NULL REFERENCES factor, tipo VARCHAR NOT NULL, nombre VARCHAR NOT NULL, enunciado VARCHAR NOT NULL, descripcion VARCHAR, activo BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS pregunta_opcion(pregunta BIGINT REFERENCES pregunta, opcion BIGINT REFERENCES opcion, puntaje DOUBLE PRECISION NOT NULL CHECK(puntaje>=0), PRIMARY KEY(pregunta,opcion));
CREATE TABLE IF NOT EXISTS empresa(nombre VARCHAR PRIMARY KEY);
CREATE TABLE IF NOT EXISTS puesto(codigo VARCHAR PRIMARY KEY, nombre VARCHAR NOT NULL, descripcion VARCHAR, activo BOOLEAN NOT NULL, empresa VARCHAR NOT NULL REFERENCES empresa);
CREATE TABLE IF NOT EXISTS requisito(puesto VARCHAR REFERENCES puesto, competencia BIGINT REFERENCES competencia, minimo DOUBLE PRECISION CHECK(minimo BETWEEN 0 AND 10), PRIMARY KEY(puesto,competencia));
CREATE TABLE IF NOT EXISTS candidato(numero INT PRIMARY KEY, apellido VARCHAR NOT NULL, nombre VARCHAR NOT NULL, tipo_doc VARCHAR NOT NULL, documento VARCHAR NOT NULL, nacimiento BIGINT, genero VARCHAR, nacionalidad VARCHAR, escolaridad VARCHAR, email VARCHAR, activo BOOLEAN NOT NULL, eliminado BOOLEAN NOT NULL, UNIQUE(tipo_doc,documento));
CREATE TABLE IF NOT EXISTS evaluacion(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, puesto VARCHAR NOT NULL REFERENCES puesto, fecha BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS cuestionario(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, evaluacion BIGINT NOT NULL REFERENCES evaluacion, candidato INT NOT NULL REFERENCES candidato, clave VARCHAR(8) UNIQUE NOT NULL, creado BIGINT NOT NULL, estado VARCHAR NOT NULL, inicio BIGINT, fin BIGINT, ultimo BIGINT, accesos INT NOT NULL, posicion INT NOT NULL, UNIQUE(evaluacion,candidato));
CREATE TABLE IF NOT EXISTS item(cuestionario BIGINT REFERENCES cuestionario, orden INT, factor BIGINT NOT NULL REFERENCES factor, enunciado VARCHAR NOT NULL, PRIMARY KEY(cuestionario,orden));
CREATE TABLE IF NOT EXISTS alternativa(cuestionario BIGINT, item INT, opcion BIGINT, texto VARCHAR NOT NULL, puntaje DOUBLE PRECISION NOT NULL, orden INT NOT NULL, PRIMARY KEY(cuestionario,item,opcion), FOREIGN KEY(cuestionario,item) REFERENCES item);
CREATE TABLE IF NOT EXISTS respuesta(cuestionario BIGINT, item INT, opcion BIGINT NOT NULL, PRIMARY KEY(cuestionario,item), FOREIGN KEY(cuestionario,item,opcion) REFERENCES alternativa);
CREATE TABLE IF NOT EXISTS auditoria(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fecha BIGINT NOT NULL, detalle VARCHAR NOT NULL, entidad VARCHAR NOT NULL);
CREATE TABLE IF NOT EXISTS version_bd(version INT PRIMARY KEY);

CREATE UNIQUE INDEX IF NOT EXISTS cuestionario_abierto_por_candidato ON cuestionario(candidato) WHERE estado IN ('ACTIVO','EN_CURSO');
